{
  "title": "社团信任考验",
  "scene": "考试结束后，社团活动中，社长突然宣布明天会有个信任考验，每个成员必须选择是否参与。你注意到社长的眼神似乎对你说着什么，但又不直接说出来。社团教室里，气氛有些微妙，大家都在窃窃私语。你手中仍握着一张从社长桌上无意间发现的便签，上面写着一句话：“信任不是盲从，而是智慧的选择。”",
  "goal": "通过信任考验，为社团贡献更多力量",
  "clue": "社长眼神、便签内容",
  "choices": [
    {"id": "A", "text": "主动请缨，直接参与信任考验", "outcome": "你勇敢地站出来，社长微笑着点头。考验顺利，你赢得了所有成员的信任。", "result": "success", "next": "next_level"},
    {"id": "B", "text": "假装生病，委婉拒绝信任考验", "outcome": "你编了个借口，拒绝了考验。社长略显失望，但没有反对。社员们似乎也接受了你的理由。虽然避免了考验，但你和社长的关系有些疏远。", "result": "partial", "next": "next_level"},
    {"id": "C", "text": "建议集体讨论，再决定是否参与", "outcome": "你提议集体讨论，最终大家同意。但是，社长的眼神里闪过一丝不满，你感觉自己的提议并没有得到全心全意的支持。虽然没有直接拒绝考验，但你感觉到了微妙的变化。", "result": "fail", "next": "retry"}
  ]
}
